"""The ``pennywise`` command line."""

import argparse
import csv
import io
import json
import os
import re
import sys

from . import ledger

_VALUE_OPTIONS = ("--category", "--since", "--until", "--by", "--format")


class _Mistake(Exception):
    """A ledger or entry mistake: exit status 1."""


class _Unreadable(Exception):
    """File problem: exit status 2."""


def _date_arg(text):
    try:
        return ledger.parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser():
    parser = argparse.ArgumentParser(
        prog="pennywise",
        description="Read a plain-text household ledger and tell where the money went.",
        allow_abbrev=False,
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    def command(name, help_text, file_help="ledger file, or - for standard input"):
        p = sub.add_parser(name, help=help_text, description=help_text, allow_abbrev=False)
        p.add_argument("file", metavar="FILE", help=file_help)
        return p

    p = command("balance", "print the total of all amounts")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("summary", "print totals per category or month")
    p.add_argument("--by", choices=("category", "month"), default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("list", "print entries, oldest first")
    p.add_argument("--category", metavar="C")
    p.add_argument("--since", metavar="DATE", type=_date_arg)
    p.add_argument("--until", metavar="DATE", type=_date_arg)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("export", "print entries as CSV, ordered like list")
    p.add_argument("--format", choices=("csv",), default="csv")

    p = command("add", "append an entry to FILE", file_help="ledger file (created if absent)")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")
    return parser


def _prepare(argv):
    """Let values that start with a dash be values, not options."""
    argv = list(argv)
    if "--" in argv:
        return argv
    if argv[:1] == ["add"]:
        if any(a in ("-h", "--help") for a in argv[1:]):
            return argv
        return ["add", "--"] + argv[1:]
    out = []
    i = 0
    while i < len(argv):
        if argv[i] in _VALUE_OPTIONS and i + 1 < len(argv):
            out.append("%s=%s" % (argv[i], argv[i + 1]))
            i += 2
        else:
            out.append(argv[i])
            i += 1
    return out


def _read(path):
    if path == "-":
        try:
            raw = getattr(sys.stdin, "buffer", None)
            if raw is not None:
                return raw.read().decode("utf-8-sig")
            return sys.stdin.read()
        except (OSError, UnicodeDecodeError) as exc:
            raise _Unreadable("pennywise: <stdin>: %s" % _why(exc)) from None
    try:
        with open(path, encoding="utf-8-sig") as handle:
            return handle.read()
    except (OSError, UnicodeDecodeError) as exc:
        raise _Unreadable("pennywise: %s: %s" % (path, _why(exc))) from None


def _why(exc):
    return exc.strerror if isinstance(exc, OSError) and exc.strerror else str(exc)


def _load(path):
    text = _read(path)
    try:
        return ledger.parse(text)
    except ledger.ParseError as exc:
        name = "<stdin>" if path == "-" else path
        raise _Mistake("pennywise: %s: %s" % (name, exc)) from None


def _sorted(entries):
    return sorted(entries, key=lambda e: e.date)


def _lines(lines):
    return "".join(line + "\n" for line in lines)


def _json(value):
    return json.dumps(value) + "\n"


def _balance(args):
    total = ledger.format_amount(ledger.balance(_load(args.file)))
    return _json({"balance": total}) if args.json else total + "\n"


def _summary(args):
    entries = _load(args.file)
    totals = ledger.by_category(entries) if args.by == "category" else ledger.by_month(entries)
    shown = {name: ledger.format_amount(totals[name]) for name in sorted(totals)}
    if args.json:
        return _json(shown)
    return _lines("%s  %s" % item for item in shown.items())


def _list(args):
    entries = _load(args.file)
    entries = ledger.filter_entries(entries, args.category, args.since, args.until)
    entries = _sorted(entries)
    if args.json:
        return _json(
            [
                {
                    "date": e.date.isoformat(),
                    "category": e.category,
                    "amount": ledger.format_amount(e.amount),
                    "note": e.note,
                }
                for e in entries
            ]
        )
    return _lines(ledger.format_entry(e) for e in entries)


def _export(args):
    entries = _sorted(_load(args.file))
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        writer.writerow([e.date.isoformat(), e.category, ledger.format_amount(e.amount), e.note])
    return buffer.getvalue()


def _add(args):
    fields = (args.date, args.category, args.amount)
    for label, value in zip(("date", "category", "amount"), fields):
        if not value or re.search(r"\s", value):
            raise _Mistake("pennywise: line 1: %s must be one word without spaces" % label)
    if re.search(r"[\r\n]", args.note):
        raise _Mistake("pennywise: line 1: note must not contain a line break")
    try:
        (entry,) = ledger.parse(" ".join(fields + (args.note,)))
    except ledger.ParseError as exc:
        raise _Mistake("pennywise: %s" % exc) from None
    line = ledger.format_entry(entry)
    try:
        data = (line + "\n").encode("utf-8")
    except UnicodeEncodeError:
        raise _Mistake("pennywise: line 1: not valid text") from None
    try:
        with open(args.file, "ab+") as handle:
            handle.seek(0, os.SEEK_END)
            if handle.tell():
                handle.seek(-1, os.SEEK_END)
                if handle.read(1) not in (b"\n", b"\r"):
                    data = b"\n" + data
            handle.write(data)
    except OSError as exc:
        raise _Unreadable("pennywise: %s: %s" % (args.file, _why(exc))) from None
    return line + "\n"


_COMMANDS = {
    "balance": _balance,
    "summary": _summary,
    "list": _list,
    "export": _export,
    "add": _add,
}


def _emit(text):
    try:
        sys.stdout.write(text)
        sys.stdout.flush()
    except BrokenPipeError:
        _silence_stdout()
    except (OSError, UnicodeEncodeError) as exc:
        _silence_stdout()
        print("pennywise: cannot write output: %s" % _why(exc), file=sys.stderr)
        return 2
    return 0


def _silence_stdout():
    # Keep the interpreter's exit-time flush from failing again.
    try:
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv=None):
    """Run the command line; return the exit status."""
    if argv is None:
        argv = sys.argv[1:]
    parser = _build_parser()
    try:
        args = parser.parse_args(_prepare(argv))
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    try:
        output = _COMMANDS[args.command](args)
    except _Mistake as exc:
        print(exc, file=sys.stderr)
        return 1
    except _Unreadable as exc:
        print(exc, file=sys.stderr)
        return 2
    return _emit(output)
"""Ledger entries: parsing, totals, filtering and formatting."""

import datetime
import decimal
import re
from dataclasses import dataclass
from decimal import Decimal

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(\.[0-9]{1,2})?")
_LINE_BREAK_RE = re.compile(r"\r\n|\r|\n")

# Exact arithmetic: the default context rounds at 28 significant digits.
_EXACT = decimal.Context(
    prec=decimal.MAX_PREC,
    Emax=decimal.MAX_EMAX,
    Emin=decimal.MIN_EMIN,
    traps=[decimal.InvalidOperation, decimal.DivisionByZero, decimal.Overflow],
)
_CENT = Decimal("0.01")


class ParseError(ValueError):
    """A line of the ledger is a mistake. ``line`` is its 1-based number."""

    def __init__(self, line, reason):
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def parse_date(text):
    """Return the ``datetime.date`` for ``YYYY-MM-DD``; ValueError otherwise."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r (expected YYYY-MM-DD)" % text)
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:]))
    except ValueError:
        raise ValueError("invalid date %r (no such day)" % text) from None


def parse_amount(text):
    """Return the ``Decimal`` for an amount with at most two decimals."""
    if not _AMOUNT_RE.fullmatch(text):
        raise ValueError("invalid amount %r (at most two decimals)" % text)
    return Decimal(text)


def parse(text):
    """Parse ledger text into a list of ``Entry`` in file order."""
    if text.startswith("﻿"):
        text = text[1:]
    entries = []
    for number, line in enumerate(_LINE_BREAK_RE.split(text), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        parts = stripped.split(None, 3)
        if len(parts) < 3:
            raise ParseError(number, "expected DATE CATEGORY AMOUNT [NOTE]")
        try:
            date = parse_date(parts[0])
            amount = parse_amount(parts[2])
        except ValueError as exc:
            raise ParseError(number, str(exc)) from None
        note = parts[3].strip() if len(parts) == 4 else ""
        entries.append(Entry(date, parts[1].lower(), amount, note))
    return entries


def balance(entries):
    """Total of all amounts (``Decimal``; zero when empty)."""
    total = Decimal(0)
    for entry in entries:
        total = _EXACT.add(total, entry.amount)
    return total


def _totals(entries, key):
    totals = {}
    for entry in entries:
        k = key(entry)
        totals[k] = _EXACT.add(totals.get(k, Decimal(0)), entry.amount)
    return totals


def by_category(entries):
    """Dict of category -> total."""
    return _totals(entries, lambda e: e.category)


def by_month(entries):
    """Dict of ``"YYYY-MM"`` -> total."""
    return _totals(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


def filter_entries(entries, category=None, since=None, until=None):
    """Entries matching category (any case) and inclusive date bounds."""
    if category is not None:
        category = category.lower()
    result = []
    for entry in entries:
        if category is not None and entry.category != category:
            continue
        if since is not None and entry.date < since:
            continue
        if until is not None and entry.date > until:
            continue
        result.append(entry)
    return result


def format_amount(amount):
    """Amount with exactly two decimals; negative zero prints as 0.00."""
    q = amount.quantize(_CENT, context=_EXACT)
    if not q:
        q = q.copy_abs()
    return format(q, "f")


def format_entry(entry):
    """``DATE CATEGORY AMOUNT[ NOTE]``, as ``list`` prints it."""
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    if entry.note:
        line += " " + entry.note
    return line
